const trigger = $('Gatilho WhatsApp').first().json;
let msg = trigger.messages ? trigger.messages[0] : null;
if (!msg && trigger.entry) { const ch = trigger.entry[0].changes[0].value; msg = ch.messages ? ch.messages[0] : null; }
const from = (msg && msg.from) || '';
let texto = '';
if (msg && msg.type === 'button') texto = msg.button.text || msg.button.payload || '';
else if (msg && msg.type === 'interactive') texto = (msg.interactive.button_reply && msg.interactive.button_reply.title) || '';
else if (msg && msg.type === 'text') texto = (msg.text && msg.text.body) || '';
const t = texto.toLowerCase();
let status = 'Verificando';
if (t.includes('resolvi')) status = 'Aguardando validacao';
else if (t.includes('suporte')) status = 'Suporte';
else if (t.includes('verific')) status = 'Verificando';
const cameras = $input.all().map(i => i.json).filter(c => String(c.responsavel_telefone || '').replace(/\D/g,'') === String(from).replace(/\D/g,''));
const out = [];
for (const c of cameras) {
  if (String(c.status || '') === 'Resolvido') continue;
  out.push({ json: { id: c.id, status: status, observacoes: (c.observacoes || '') + (texto ? ' | Resp: ' + texto : '') } });
}
out.push({ json: { _meta: true, from: from, texto: texto, status: status } });
return out;

const meta = $('Processar resposta').all().find(i => i.json._meta);
const m = meta ? meta.json : {};
return [{ json: { timestamp: new Date().toISOString(), camera_id: '', camera_nome: '', responsavel_telefone: m.from || '', acao: 'RESPOSTA_RECEBIDA', detalhe: 'Resposta: ' + (m.texto || '') + ' -> ' + (m.status || ''), status_anterior: '', status_novo: m.status || '' } }];

const meta = $('Processar resposta').all().find(i => i.json._meta);
const m = meta ? meta.json : {};
const statusMsg = m.status === 'Aguardando validacao' ? 'marcada como aguardando validacao.' : (m.status === 'Suporte' ? 'encaminhada para suporte.' : 'atualizada para ' + m.status + '.');
return [{ json: { to: m.from, body: 'Recebemos sua resposta. Suas cameras foram ' + statusMsg } }];
